syntax = "proto3";
package plant;

message Location {
  string site = 1;
  string line = 2;
}

enum Unit {
  UNIT_UNSPECIFIED = 0;
  CELSIUS = 1;
  BAR = 2;
}

syntax = "proto3";
package plant;

import "plant/common.proto";

message Telemetry {
  string device = 1;
  Location location = 2;
  double temperature = 3;
  Unit unit = 4;
  int64 counter = 5;
  bool running = 6;
}

message Alarm {
  string device = 1;
  int32 code = 2;
  string text = 3;
}
